<template><div class="page"><div class="page-lead"><div><span class="eyebrow">系统会带你一步一步完成</span><h2 class="page-title">{{headline}}</h2><p class="muted">不用一次看懂所有功能，只完成下方提示的下一步即可。</p></div></div>
<WorkflowGuide v-if="!loading" :steps="steps" :action="data.workflow?.next_action" :button-text="data.plan?'查看本周执行':'继续下一步'"/>
<template v-if="data.plan"><div class="grid section summary-grid"><div class="card focus-card"><span class="muted">本周预算 / 已消费</span><div class="metric">{{formatMoney(data.current_week?.budget_minor)}} / {{formatMoney(data.current_week?.actual_minor)}}</div><el-progress :percentage="usage" :status="usage>100?'exception':undefined"/><small>{{data.current_week?.usage_bps==null?'本周尚无可用计划':`已使用 ${formatPercent(data.current_week.usage_bps)}`}}</small></div><div class="card"><span class="muted">当前存款</span><div class="metric">{{formatMoney(data.current_savings_minor)}}</div><small v-if="data.goal_progress_bps!=null">目标进度 {{formatPercent(data.goal_progress_bps)}}</small></div><div class="card"><span class="muted">预计期末存款</span><div class="metric">{{formatMoney(data.plan?.expected_final_savings_minor)}}</div><small>情景风险：{{riskName(data.plan?.risk_level)}}</small></div></div></template>
<div v-else-if="data.has_data" class="grid section summary-grid"><div class="card"><span class="muted">本月实际净消费</span><div class="metric">{{formatMoney(data.monthly_actual_minor)}}</div></div><div class="card"><span class="muted">当前存款</span><div class="metric">{{formatMoney(data.current_savings_minor)}}</div></div><div class="card"><span class="muted">储蓄目标</span><div class="metric">{{formatMoney(data.goal?.target_savings_minor)}}</div></div></div>
<div v-loading="loading" class="card section"><div class="section-heading"><div><h3>最近 8 周净消费</h3><p class="muted">用来了解近期正常消费变化，退款已从毛消费中扣除。</p></div><el-button v-if="data.has_data" text @click="$router.push('/analytics')">查看完整分析</el-button></div><EChart v-if="data.recent_weekly?.length" :option="chart"/><EmptyGuide v-else description="尚无消费数据" hint="导入微信账单后，这里会显示真实消费趋势。" action="/bills" action-text="导入账单"/></div></div></template>
<script setup>
import { computed,onMounted,ref } from 'vue';import { api } from '../api/client.js';import { formatMoney,formatPercent } from '../utils/money.js';import { riskLabels,workflowSteps } from '../utils/display.js';import EChart from '../components/EChart.vue';import EmptyGuide from '../components/EmptyGuide.vue';import WorkflowGuide from '../components/WorkflowGuide.vue'
const data=ref({}),loading=ref(true);onMounted(async()=>{try{data.value=await api.get('/dashboard')}finally{loading.value=false}})
const headline=computed(()=>data.value.plan?'按本周预算稳步执行':data.value.workflow?.next_action?.title||'开始你的储蓄规划');const steps=computed(()=>workflowSteps(data.value.workflow));const usage=computed(()=>Math.min(100,Math.max(0,(data.value.current_week?.usage_bps||0)/100)));const riskName=v=>riskLabels[v]||v||'暂无'
const chart=computed(()=>({tooltip:{trigger:'axis',valueFormatter:v=>formatMoney(v)},xAxis:{type:'category',data:(data.value.recent_weekly||[]).map(x=>x.week_start)},yAxis:{type:'value'},series:[{type:'line',smooth:true,areaStyle:{opacity:.12},data:(data.value.recent_weekly||[]).map(x=>x.net_consumption_minor),color:'#2b9a72'}]}))
</script>
